export function assertAdaptiveAdmissionPolicy(p){assert(p);assert.equal(p.mode,'fresh-input-exact-minimum');assert.deepEqual(p.allowedBands,[2,3]);assert.equal(p.searchFloor,21);assert.equal(p.searchUpper,128);assert.equal(p.onBandFull,'terminal-unassigned');assert.equal(p.fallbackAllowed,false);assert.equal(p.levelDifficulty,'super');assert(p.slotsByBand&&Object.keys(p.slotsByBand).sort().join(',')==='2,3');const seen=new Set();let total=0;for(const d of[2,3]){const rows=p.slotsByBand[d];assert(Array.isArray(rows)&&rows.length<=10);for(const row of rows){assert.deepEqual(Object.keys(row).sort(),['formalId','priorSlot']);descriptor(row.priorSlot);assert(new RegExp('^daily-mechanisms-axis-block-50-d'+d+'-[0-9]{2}$').test(row.formalId));assert(!seen.has(row.formalId));seen.add(row.formalId);total++;}}assert(total>0);return true;}
export function minimumBand(k){integer(k);return k<21?null:k<=30?2:3;}
/** A rejected input never consumes an accepted-slot position. The same input
 * gets exactly one queue head, even if that prior/static/strength check fails. */
export function selectAdaptiveSlot(policy,k,acceptedFormalIds=[]){assertAdaptiveAdmissionPolicy(policy);const band=minimumBand(k);if(band===null)return{status:'MINIMUM_BELOW_ALLOWED_BANDS',band:null,formalId:null};const occupied=new Set(acceptedFormalIds),row=policy.slotsByBand[band].find(s=>!occupied.has(s.formalId));return row?{status:'SLOT_SELECTED',band,formalId:row.formalId,priorSlot:row.priorSlot}:{status:'BAND_FULL_TERMINAL_UNASSIGNED',band,formalId:null};}
export function assertAdaptiveAllocation(q,policy,acceptedFormalIds,slotRows){if(!q.joint?.accepted){assert.equal(q.admission,null);assert.equal(q.formalId,null);assert.equal(q.difficulty,null);assert.equal(q.accepted,false);return null;}assert.deepEqual(q.admission,selectAdaptiveSlot(policy,q.joint.U,acceptedFormalIds));if(q.admission.status!=='SLOT_SELECTED'){assert.equal(q.status,q.admission.status);assert.equal(q.accepted,false);assert.equal(q.formalId,null);assert.equal(q.difficulty,null);assert.equal(q.staticAudit,undefined);assert(!q.phaseAccounting?.phases['static-audit']);return null;}const chosen=slotRows.find(r=>r.slot.formalId===q.admission.formalId);assert(chosen);assert.deepEqual(chosen.priorSlot,q.admission.priorSlot);for(const[k,v]of Object.entries(chosen.slot))assert.deepEqual(q[k],v);return chosen;}

