export function createAdaptivePhaseAccount(recipe,{qualificationOnly=false,now=Date.now}={}){if(!qualificationOnly)assert.equal(now,Date.now);const quotes=adaptivePhaseQuotes(recipe),rows={},order=[];let last=null;const time=()=>{const t=now();integer(t);assert(last===null||t>=last,'Phase clock reversed');last=t;return t;};return{
 begin(name){assert(quotes[name]);assert(!rows[name],'A phase cannot be restarted');const t=time();rows[name]={name,status:'RUNNING',startedAt:t,endedAt:null,elapsedMilliseconds:0,reservation:{...quotes[name]},exactWorldVisitsClaimed:false};order.push(name);},
 guard(name){const r=rows[name];assert(r&&r.status==='RUNNING');if(time()-r.startedAt>=r.reservation.maxMilliseconds)throw Error('phase-deadline:'+name);},
 finish(name,error=null){const r=rows[name];assert(r&&r.status==='RUNNING','Finish exactly one active phase');const t=time();r.endedAt=t;r.elapsedMilliseconds=t-r.startedAt;r.status=error?'TERMINAL':'COMPLETED';r.reason=error?String(error):null;if(r.elapsedMilliseconds>=r.reservation.maxMilliseconds){r.status='TERMINAL';r.reason='phase-deadline:'+name;throw Error(r.reason);}},
 report(){return structuredClone({version:STAGE_ACCOUNTING_VERSION,qualificationOnly,quotes,order,phases:rows,exactWorldVisitsClaimed:false,searchGuardIncludedInJointWorlds:true,compilerTimingCoversWholeSingleKernelCall:true});}
 };}
export function assertAdaptivePhaseAccounting(a,recipe,{qualificationOnly=false,allowRunning=false}={}){assert.equal(a.version,STAGE_ACCOUNTING_VERSION);assert.equal(a.qualificationOnly,qualificationOnly);assert.equal(a.exactWorldVisitsClaimed,false);assert.equal(a.searchGuardIncludedInJointWorlds,true);assert.equal(a.compilerTimingCoversWholeSingleKernelCall,true);assert.deepEqual(a.quotes,adaptivePhaseQuotes(recipe));assert.equal(new Set(a.order).size,a.order.length);assert.deepEqual(Object.keys(a.phases),a.order);assert.deepEqual(a.order,['spatial-compile','joint-search','dual-replay','static-audit','admission-metadata'].slice(0,a.order.length));for(const name of a.order){const r=a.phases[name];assert.equal(r.name,name);assert.deepEqual(r.reservation,a.quotes[name]);assert.equal(r.exactWorldVisitsClaimed,false);integer(r.startedAt);integer(r.elapsedMilliseconds);if(r.status==='RUNNING'){assert(allowRunning);assert.equal(r.endedAt,null);}else{assert(['COMPLETED','TERMINAL'].includes(r.status));integer(r.endedAt,r.startedAt);assert.equal(r.elapsedMilliseconds,r.endedAt-r.startedAt);if(r.status==='COMPLETED'){assert.equal(r.reason,null);assert(r.elapsedMilliseconds<r.reservation.maxMilliseconds);}else assert(typeof r.reason==='string'&&r.reason);}}return true;}
