 for(const [i,d]of drags.entries()){const b=level.blocks.find(b=>b.id===d.blockId);assert(b);assert(clears>=(b.frozen??0),'Frozen body acted before actual thaw');if(!actions.has(b.id))actions.set(b.id,[]);actions.get(b.id).push({drag:i+1,clearsBefore:clears,unitSteps:d.path.length,exit:!!d.exitSide});const after=clears+independent.trace[i].clearDelta;for(const [id,b]of iceById)if(clears<b.frozen&&after>=b.frozen){assert.equal(after,b.frozen);assert(!thaws.has(id));thaws.set(id,{drag:i+1,clearCount:after});}clears=after;}
 const details=ice.map(b=>{const thaw=thaws.get(b.id),moves=actions.get(b.id)??[],exit=facts.exits.find(e=>e.blockId===b.id);assert(thaw&&moves.length&&exit,'Every real ice body must thaw, act and clear');assert(moves[0].drag>thaw.drag);assert.equal(thaw.clearCount,b.frozen);assert(moves.every(a=>a.clearsBefore>=b.frozen));return{id:b.id,value:b.frozen,active:true,evidence:{thawDrag:thaw.drag,thawClearCount:thaw.clearCount,firstAction:moves[0].drag,firstActionClearsBefore:moves[0].clearsBefore,unitSteps:moves.reduce((n,a)=>n+a.unitSteps,0),realExitDrag:exit.drag,clearsBeforeExit:exit.clearsBefore}};});
