export function assertJointProof(proof,levelHash,rt,budget,{floor=31}={}){assert.equal(proof.sourceLevelSha256,levelHash);assert.equal(proof.contractVersion,AXIS_ICE_PROOF_VERSION);assert.equal(proof.axisIceProofSha256,rt.axisIceProofSha256);assert.deepEqual(proof.axisIceBindings,rt.axisIceBindings);assert.deepEqual(proof.budget,budget);assert.equal(proof.floor,floor);assert.deepEqual(inspectSearchAccounting(proof,'wholeboard-axis-ice'),[]);assert.deepEqual(proof.guardAllowance,guardAllowanceFor(proof));return true;}
