/** One unchanged joint call, then the two original interpreters. No retry,
 * projected graph, route replacement or extra participation replay. */
export function solveWholeBoardJoint(rt,level,recipe,phases,{qualificationOnly=false,floor=21}={}){
 if(qualificationOnly){assert(level.id>=990000&&level.width*level.height<=16&&level.blocks.length<=8);}else{assertWholeBoardMechanisms(level,recipe);assert.equal(floor,21);assert.equal(level.difficulty,'super');}
 const budget={...JOINT_BUDGET},result={budget,proof:null,route:null,drags:null,U:null,L:null,exactMinimum:null,accepted:false,mathematicalSearchInvocations:0,canonicalReplayInvocations:0,independentReplayInvocations:0};
 try{phases.begin('spatial-compile');phases.begin('joint-search');result.mathematicalSearchInvocations=1;const raw=boundedAxisIceTask(level,rt,{floor,searchUpper:128,...budget});result.proof={...raw,guardAllowance:guardAllowanceFor(raw)};
  let finishError=null;for(const name of['joint-search','spatial-compile']){try{phases.finish(name);}catch(e){finishError??=e;}}if(finishError)throw finishError;
  assertJointProof(result.proof,levelSha256(level),rt,budget,{floor});const drags=requireCompleteJointWitness(result.proof,floor);result.drags=drags;result.routeSha256=routeSha256(drags);result.actualReplayQuote=assertWitnessEnvelope(recipe,drags);
  phases.begin('dual-replay');result.route={search:result.proof,inputLevelSha256:levelSha256(level),routeSha256:result.routeSha256,canonicalReplay:null,independentReplay:null};result.canonicalReplayInvocations=1;result.route.canonicalReplay=rt.replayRevisedRoute(level,drags);phases.guard('dual-replay');result.independentReplayInvocations=1;result.route.independentReplay=independentReplay(rt,level,drags);phases.finish('dual-replay');assertRouteDual(level,drags,result.route.canonicalReplay,result.route.independentReplay);
  result.exactMinimum=deriveAdaptiveExactCertificate(level,result,rt,{qualificationOnly,floor});result.U=result.exactMinimum.U;result.L=result.exactMinimum.L;result.accepted=true;result.status='ORIGINAL_WHOLEBOARD_AXIS_ICE_EXACT_MINIMUM_VERIFIED';
 }catch(e){result.status='WHOLEBOARD_JOINT_TERMINAL';result.reason=e.message;for(const[name,r]of Object.entries(phases.report().phases))if(r.status==='RUNNING')try{phases.finish(name,e.message);}catch{};result.accepted=false;result.L=null;result.U=null;}
 result.accountingAtReturn=phases.report();return result;
}

async function bindTools(r,rt){await r.map(rt.toolchainBindings);await r.map(rt.designBindings);await r.map(rt.axisIceBindings);const compiled=await build({entryPoints:[SELF],bundle:true,packages:'external',write:false,metafile:true,platform:'node',format:'esm',logLevel:'silent'});for(const p of Object.keys(compiled.metafile.inputs))await r.bytes(p);}
