function declaredMembers(h,d){const canonical=compileCanonicalHistoryPath(h.bundle.scope).canonical,out=Object.fromEntries(h.bundle.scope.roots.map(r=>[r.id,[]])),seen=new Set();for(const f of [...h.bundle.files,...d.files])if(f.rootId!==null){const k=canonical(f.path);assert(!seen.has(k));seen.add(k);assert(out[f.rootId]);out[f.rootId].push(f.path);}return out;}
async function members(h,allowed=[]){const canonical=compileCanonicalHistoryPath(h.bundle.scope).canonical,rows=[];for(const p of new Set(allowed)){const root=h.bundle.scope.roots.find(r=>canonical(p).startsWith(canonical(r.physicalPath)+'/'));if(root)rows.push({rootId:root.id,path:p});}return assertPlanHistoryMembers(h,await listing(h.bundle.scope),rows);}
