async function qualification(r,d){const q=await r.bound(d);assert.equal(q.status,QUALIFICATION_STATUS);assert.deepEqual(q.errors,[]);for(const k of ['newRealConstructions','newSearches','publicClaimsStarted'])assert.equal(q[k],0);for(const p of [SELF,FACTORY,AXIS_PRIMITIVE])assert(q.toolBindings[p]);await r.map(q.toolBindings);}

