 const rt=await loadWholeBoardRuntime(),environment=prefixExecutionEnvironment(rt);await bindTools(r,rt);await r.map(environment.bindings);await qualification(r,c.qualification);const h=await loadHistoryOnce(r,c);assert(!h.closedExperimentIds.includes(c.experimentId));const view=await readSupplementalComparisonEvidence(h,{...c.comparison,readBytes:p=>r.bytes(p),qualificationOnly:false,role:'comparison-only'});if(!deferMembers)await members(h);
