 const preparedRecipes=[];for(const recipe of proposal.recipes){assertWholeBoardRecipe(recipe);const source=rt.LEVELS.find(l=>l.id===recipe.sourceLevelId);assert(source);assert.equal(levelSha256(source),recipe.source.levelSha256);assert.deepEqual([source.width,source.height],[recipe.source.width,recipe.source.height]);const sourceBinding=await currentMainlineSourceBinding(rt,environment,recipe.sourceLevelId);await r.map(sourceBinding.bindings);const catalogue=await r.bound(recipe.source.catalogue),row=catalogue.rows.find(s=>s.sourceLevelId===recipe.sourceLevelId);assertWholeBoardSourceJson(row.level,source);assert.equal(row.maskSha256,recipe.source.maskSha256);preparedRecipes.push({recipe,source,parent:parents.get(recipe.sourceLevelId)});}
