function prepared(x,d){return{version:VERSION,contextDescriptor:d,experimentId:x.c.experimentId,proposal:x.c.proposal,proposalReview:x.c.proposalReview,maximumInputs:x.preparedRecipes.length,parentResolutionPolicy:BATCH_PARENT_POLICY,initialFailedParents:x.parentSeeds.map(p=>p.evidence),admissionPolicy:x.proposal.admissionPolicy,slotRows:x.slotRows.map(r=>({slot:r.slot,priorSlot:r.priorSlot})),recipes:x.preparedRecipes.map(x=>({recipe:x.recipe,initialFailedParent:x.parent.evidence,parentResolutionPolicy:BATCH_PARENT_POLICY,sourceLevelSha256:levelSha256(x.source),futureReservationsDeclared:futureReservations(x.recipe),phaseQuotes:adaptivePhaseQuotes(x.recipe),jointBudget:JOINT_BUDGET,rawSetMaximum:9999,searchGuardAllowance:1})),historyHeadSha256:x.h.headSha256,comparisonEvidence:x.view.comparisonEvidence,coreDiversityScope:x.coreIndex.stats(),environment:x.environment,constructionLimits:LIMITS,stageAccountingVersion:STAGE_ACCOUNTING_VERSION,historyLoads:1,runtimeLoads:1,firstFullIsTerminal:true,bindings:x.r.bindings,accepted:false,formalReady:false};}
