export function assertWholeBoardConstruction(built,recipe,{qualificationOnly=false}={}){assert.equal(built.recipeSha256,recipeIdentity(recipe));assertWholeBoardAccounting(built.accounting,{qualificationOnly});assert.deepEqual(built.accounting,built.constructionAccounting.accounting);const c=built.constructionAccounting;assert.equal(c.version,FACTORY_VERSION);assert.equal(c.version,built.accounting.version);assert.equal(c.qualificationOnly,qualificationOnly);assert.equal(c.recipeSha256,built.recipeSha256);if(!qualificationOnly)assert.equal(c.sourceLevelSha256,recipe.source.levelSha256);assert.equal(c.status,built.status);assert.equal(c.reason,built.reason);assert.equal(built.accounting.partialNodes,c.partialAssignmentCount.gate+c.partialAssignmentCount.body);assert.equal(c.placeholderWorlds,0);for(const k of['newModels','newSearches','newReplays','newClaims'])assert.equal(c[k],0);assert.equal(built.found,!!built.level);assert.equal(c.firstFullWorlds,Number(!!built.level));assert.equal(c.budgetAccountingVersion,'stage-separated-construction-v1');assert.equal(c.stageSeparated,true);assert.equal(c.futureReservationsPaid,false);assert.equal(c.futureVerificationExecuted,false);if(!qualificationOnly)assert.deepEqual(c.futureReservationsDeclared,futureReservations(recipe));const first=built.accounting.reservations.filter(r=>r.reason==='construction-first-full-world');
 if(!built.level){assert.equal(built.level,null);assert.equal(built.levelSha256,null);assert.equal(built.firstFullReceipt,null);assert.equal(c.firstFullReceipt,null);assert.equal(first.length,0);assert.equal(built.accounting.worlds,0);assert.notEqual(built.status,'FIRST_FULL_AXIS_ICE_TERMINAL');}
 else{assert.equal(built.levelSha256,levelSha256(built.level));assert.equal(first.length,1);const f=built.firstFullReceipt;assert.deepEqual(c.firstFullReceipt,f);assert.equal(f.levelSha256,built.levelSha256);assert.equal(f.firstFullWorlds,1);assert.equal(f.allMechanismsBeforeFirstHash,true);assert.equal(f.firstCompleteIsTerminal,true);assert.equal(f.budgetAccountingVersion,'stage-separated-construction-v1');assert.equal(f.stageSeparated,true);assert.equal(f.futureReservationsPaid,false);assert.equal(f.futureVerificationExecuted,false);assert.equal(f.prepaidPhases,undefined);assert.deepEqual(f.constructionReservation,{worlds:1,transitions:0,micro:0});assert.deepEqual(f.reservation,f.constructionReservation);assert.deepEqual(first[0],{reason:'construction-first-full-world',...f.constructionReservation});assert.equal(built.accounting.worlds,1);if(!qualificationOnly){assertWholeBoardMechanisms(built.level,recipe);assert.deepEqual(f.futureReservationsDeclared,futureReservations(recipe));}}return true;}
export function assertWholeBoardPhaseAccounting(built,final,joint){assert.deepEqual(final,built.accounting,'Construction account stops with its one terminal result; verification is separate');return true;}
